-- Sua chu tieng Viet cua 70 ban ghi seed da nap qua SQL*Plus sai client charset.
-- Chi cap nhat 33 ban ghi danh muc co cot van ban; khong xoa, khong nap lai.
WHENEVER SQLERROR EXIT SQL.SQLCODE ROLLBACK
SET DEFINE OFF
BEGIN IF USER <> 'FASHION_ADMIN' OR LOWER(SYS_CONTEXT('USERENV','CON_NAME')) <> 'orcl' THEN RAISE_APPLICATION_ERROR(-20001, 'Wrong owner or container'); END IF; END;
/
